// ?ConstructNetCommandMsgFromRawData@NetPacket@@SAPAVNetCommandRef@@PAEG@Z
// partial score=0.88 date=2026-09-10
// cl: /DNDEBUG /DWIN32 /D_WINDOWS /MD /EHsc
//
// NetPacket::ConstructNetCommandMsgFromRawData, retail RVA 0x0067EE40,
// 940 bytes.  The named getReadyCommands caller reaches this body through
// ILT 0x00048301.  The BFME wire-format reader destinations and their
// command-type mapping are independently matched in NetPacket_read*.cpp.
//
// This TU keeps the BFME de-pooled command ABI local.  NetPacket.cpp still
// carries the upstream-shaped present-unmatched implementation; the build
// selects this TU for the retail body, as it does for the other split
// NetPacket readers.

#include <string.h>

#define NULL 0

typedef unsigned char UnsignedByte;
typedef unsigned short UnsignedShort;
typedef unsigned int UnsignedInt;
typedef int Int;
typedef bool Bool;

enum NetCommandType {
	NETCOMMANDTYPE_ACKBOTH = 0,
	NETCOMMANDTYPE_ACKSTAGE1 = 1,
	NETCOMMANDTYPE_ACKSTAGE2 = 2,
	NETCOMMANDTYPE_FRAMEINFO = 3,
	NETCOMMANDTYPE_GAMECOMMAND = 4,
	NETCOMMANDTYPE_REQUESTGAMESPYSTATSAUTHKEY = 5,
	NETCOMMANDTYPE_GAMESPYSTATSAUTHKEY = 6,
	NETCOMMANDTYPE_REQUESTPLAYERLEAVE = 7,
	NETCOMMANDTYPE_INFORMPLAYERLEAVEFRAME = 8,
	NETCOMMANDTYPE_REQUESTFRAMEDATA = 9,
	NETCOMMANDTYPE_PLAYERLEAVE = 10,
	NETCOMMANDTYPE_DESTROYPLAYER = 11,
	NETCOMMANDTYPE_KEEPALIVE = 12,
	NETCOMMANDTYPE_DISCONNECTCHAT = 13,
	NETCOMMANDTYPE_CHAT = 14,
	NETCOMMANDTYPE_PROGRESS = 15,
	NETCOMMANDTYPE_LOADCOMPLETE = 16,
	NETCOMMANDTYPE_TIMEOUTSTART = 17,
	NETCOMMANDTYPE_WRAPPER = 18,
	NETCOMMANDTYPE_FILE = 19,
	NETCOMMANDTYPE_FILEANNOUNCE = 20,
	NETCOMMANDTYPE_FILEPROGRESS = 21,
	NETCOMMANDTYPE_ROUTERFALLBACK = 22,
	NETCOMMANDTYPE_DISCONNECTSTART = 23,
	NETCOMMANDTYPE_DISCONNECTKEEPALIVE = 24,
	NETCOMMANDTYPE_DISCONNECTPLAYER = 25,
	NETCOMMANDTYPE_DISCONNECTVOTE = 26,
	NETCOMMANDTYPE_DISCONNECTFRAME = 27,
	NETCOMMANDTYPE_DISCONNECTSCREENOFF = 28
};

#define TRUE true
#define FALSE false

class NetCommandMsg {
public:
	void setExecutionFrame(UnsignedInt frame) { m_frame = frame; }
	void setID(UnsignedShort id) { m_id = id; }
	void setPlayerID(UnsignedInt player) { m_player = player; }
	void setNetCommandType(NetCommandType type) { m_type = type; }
	void detach();

private:
	void *m_vptr;
	UnsignedInt m_timestamp;
	UnsignedInt m_frame;
	UnsignedInt m_player;
	UnsignedShort m_id;
	NetCommandType m_type;
	Int m_referenceCount;
};

class NetCommandRef {
public:
	NetCommandRef(NetCommandMsg *msg);
	void setRelay(UnsignedByte relay) { m_relay = relay; }

private:
	NetCommandMsg *m_msg;
	NetCommandRef *m_next;
	NetCommandRef *m_prev;
	UnsignedByte m_relay;
	UnsignedInt m_timeLastSent;
};

class NetPacket {
public:
	static NetCommandRef *ConstructNetCommandMsgFromRawData(UnsignedByte *data,
		UnsignedShort dataLength);

protected:
	static NetCommandMsg *readGameMessage(UnsignedByte *data, Int &offset);
	static NetCommandMsg *readAckBothMessage(UnsignedByte *data, Int &offset);
	static NetCommandMsg *readAckStage1Message(UnsignedByte *data, Int &offset);
	static NetCommandMsg *readAckStage2Message(UnsignedByte *data, Int &offset);
	static NetCommandMsg *readFrameMessage(UnsignedByte *data, Int &offset);
	static NetCommandMsg *readRouterFallbackMessage(UnsignedByte *data, Int &offset);
	static NetCommandMsg *readPlayerLeaveMessage(UnsignedByte *data, Int &offset);
	static NetCommandMsg *readDestroyPlayerMessage(UnsignedByte *data, Int &offset);
	static NetCommandMsg *readKeepAliveMessage(UnsignedByte *data, Int &offset);
	static NetCommandMsg *readDisconnectKeepAliveMessage(UnsignedByte *data, Int &offset);
	static NetCommandMsg *readDisconnectPlayerMessage(UnsignedByte *data, Int &offset);
	static NetCommandMsg *readDisconnectChatMessage(UnsignedByte *data, Int &offset);
	static NetCommandMsg *readDisconnectVoteMessage(UnsignedByte *data, Int &offset);
	static NetCommandMsg *readChatMessage(UnsignedByte *data, Int &offset);
	static NetCommandMsg *readProgressMessage(UnsignedByte *data, Int &offset);
	static NetCommandMsg *readLoadCompleteMessage(UnsignedByte *data, Int &offset);
	static NetCommandMsg *readTimeOutGameStartMessage(UnsignedByte *data, Int &offset);
	static NetCommandMsg *readWrapperMessage(UnsignedByte *data, Int &offset);
	static NetCommandMsg *readFileMessage(UnsignedByte *data, Int &offset);
	static NetCommandMsg *readFileAnnounceMessage(UnsignedByte *data, Int &offset);
	static NetCommandMsg *readFileProgressMessage(UnsignedByte *data, Int &offset);
	static NetCommandMsg *readInformPlayerLeaveFrameMessage(UnsignedByte *data, Int &offset);
	static NetCommandMsg *readRequestPlayerLeaveMessage(UnsignedByte *data, Int &offset);
	static NetCommandMsg *readRequestFrameDataMessage(UnsignedByte *data, Int &offset);
	static NetCommandMsg *readDisconnectFrameMessage(UnsignedByte *data, Int &offset);
	static NetCommandMsg *readDisconnectScreenOffMessage(UnsignedByte *data, Int &offset);
	static NetCommandMsg *readRequestGameSpyStatsAuthKeyMessage(UnsignedByte *data, Int &offset);
	static NetCommandMsg *readGameSpyStatsAuthKeyMessage(UnsignedByte *data, Int &offset);
};

NetCommandRef *NetPacket::ConstructNetCommandMsgFromRawData(UnsignedByte *data,
	UnsignedShort dataLength)
{
	NetCommandType commandType = NETCOMMANDTYPE_ACKBOTH;
	UnsignedShort commandID = 0;
	UnsignedInt frame = 0;
	UnsignedByte playerID = 0;
	UnsignedByte relay = 0;

	Int offset = 0;
	Bool notDone = TRUE;
	NetCommandRef *ref = NULL;

	while ((offset < (Int)dataLength) && notDone) {
		// Keeping the raw buffer as a loop-local view is intentional: retail
		// keeps the packet pointer separate from the cursor across dispatch.
		UnsignedByte *rawData = data;

		if (rawData[offset] == 'T') {
			++offset;
			memcpy(&commandType, rawData + offset, sizeof(UnsignedByte));
			offset += sizeof(UnsignedByte);
		} else if (rawData[offset] == 'R') {
			++offset;
			memcpy(&relay, rawData + offset, sizeof(UnsignedByte));
			offset += sizeof(UnsignedByte);
		} else if (rawData[offset] == 'P') {
			++offset;
			memcpy(&playerID, rawData + offset, sizeof(UnsignedByte));
			offset += sizeof(UnsignedByte);
		} else if (rawData[offset] == 'C') {
			++offset;
			memcpy(&commandID, rawData + offset, sizeof(UnsignedShort));
			offset += sizeof(UnsignedShort);
		} else if (rawData[offset] == 'F') {
			++offset;
			memcpy(&frame, rawData + offset, sizeof(UnsignedInt));
			offset += sizeof(UnsignedInt);
		} else if (rawData[offset] == 'D') {
			++offset;
			Int payloadOffset = offset;
			NetCommandMsg *msg = NULL;

			if (commandType == NETCOMMANDTYPE_GAMECOMMAND) {
				msg = readGameMessage(rawData, payloadOffset);
			} else if (commandType == NETCOMMANDTYPE_ACKBOTH) {
				msg = readAckBothMessage(rawData, payloadOffset);
			} else if (commandType == NETCOMMANDTYPE_ACKSTAGE1) {
				msg = readAckStage1Message(rawData, payloadOffset);
			} else if (commandType == NETCOMMANDTYPE_ACKSTAGE2) {
				msg = readAckStage2Message(rawData, payloadOffset);
			} else if (commandType == NETCOMMANDTYPE_FRAMEINFO) {
				msg = readFrameMessage(rawData, payloadOffset);
			} else if (commandType == NETCOMMANDTYPE_ROUTERFALLBACK) {
				msg = readRouterFallbackMessage(rawData, payloadOffset);
			} else if (commandType == NETCOMMANDTYPE_PLAYERLEAVE) {
				msg = readPlayerLeaveMessage(rawData, payloadOffset);
			} else if (commandType == NETCOMMANDTYPE_DESTROYPLAYER) {
				msg = readDestroyPlayerMessage(rawData, payloadOffset);
			} else if (commandType == NETCOMMANDTYPE_KEEPALIVE) {
				msg = readKeepAliveMessage(rawData, payloadOffset);
			} else if (commandType == NETCOMMANDTYPE_DISCONNECTKEEPALIVE) {
				msg = readDisconnectKeepAliveMessage(rawData, payloadOffset);
			} else if (commandType == NETCOMMANDTYPE_DISCONNECTPLAYER) {
				msg = readDisconnectPlayerMessage(rawData, payloadOffset);
			} else if (commandType == NETCOMMANDTYPE_DISCONNECTCHAT) {
				msg = readDisconnectChatMessage(rawData, payloadOffset);
			} else if (commandType == NETCOMMANDTYPE_DISCONNECTVOTE) {
				msg = readDisconnectVoteMessage(rawData, payloadOffset);
			} else if (commandType == NETCOMMANDTYPE_CHAT) {
				msg = readChatMessage(rawData, payloadOffset);
			} else if (commandType == NETCOMMANDTYPE_PROGRESS) {
				msg = readProgressMessage(rawData, payloadOffset);
			} else if (commandType == NETCOMMANDTYPE_LOADCOMPLETE) {
				msg = readLoadCompleteMessage(rawData, payloadOffset);
			} else if (commandType == NETCOMMANDTYPE_TIMEOUTSTART) {
				msg = readTimeOutGameStartMessage(rawData, payloadOffset);
			} else if (commandType == NETCOMMANDTYPE_WRAPPER) {
				msg = readWrapperMessage(rawData, payloadOffset);
			} else if (commandType == NETCOMMANDTYPE_FILE) {
				msg = readFileMessage(rawData, payloadOffset);
			} else if (commandType == NETCOMMANDTYPE_FILEANNOUNCE) {
				msg = readFileAnnounceMessage(rawData, payloadOffset);
			} else if (commandType == NETCOMMANDTYPE_FILEPROGRESS) {
				msg = readFileProgressMessage(rawData, payloadOffset);
			} else if (commandType == NETCOMMANDTYPE_INFORMPLAYERLEAVEFRAME) {
				msg = readInformPlayerLeaveFrameMessage(rawData, payloadOffset);
			} else if (commandType == NETCOMMANDTYPE_REQUESTPLAYERLEAVE) {
				msg = readRequestPlayerLeaveMessage(rawData, payloadOffset);
			} else if (commandType == NETCOMMANDTYPE_REQUESTFRAMEDATA) {
				msg = readRequestFrameDataMessage(rawData, payloadOffset);
			} else if (commandType == NETCOMMANDTYPE_DISCONNECTFRAME) {
				msg = readDisconnectFrameMessage(rawData, payloadOffset);
			} else if (commandType == NETCOMMANDTYPE_DISCONNECTSCREENOFF) {
				msg = readDisconnectScreenOffMessage(rawData, payloadOffset);
			} else if (commandType == NETCOMMANDTYPE_REQUESTGAMESPYSTATSAUTHKEY) {
				msg = readRequestGameSpyStatsAuthKeyMessage(rawData, payloadOffset);
			} else if (commandType == NETCOMMANDTYPE_GAMESPYSTATSAUTHKEY) {
				msg = readGameSpyStatsAuthKeyMessage(rawData, payloadOffset);
			}

			if (msg == NULL) {
				return NULL;
			}

			msg->setExecutionFrame(frame);
			msg->setID(commandID);
			msg->setPlayerID(playerID);
			msg->setNetCommandType(commandType);

			ref = new NetCommandRef(msg);
			ref->setRelay(relay);

			offset = payloadOffset;
			msg->detach();
			msg = NULL;
			notDone = FALSE;
		}
	}

	return ref;
}
